// ============================================================================
//  «DEBATE TÚ»: catorce pensadores más (Platón, Aristóteles, Epicuro, Hobbes,
//  Rousseau, Hume, Marx, Mill, Beauvoir, Camus, Arendt, Confucio, Buda y
//  Agustín), con objeciones clásicas de la historia de la filosofía.
//  (datos sin dependencias: también los leen las herramientas de voz)
// ============================================================================
POSTURAS.push(
  {"id": "platon", "q": "¿Hay algo más real que lo que vemos?", "rounds": [{"say": "Las cosas que vemos cambian: la flor se marchita, el cuerpo envejece. Pero la Belleza en sí no cambia nunca. Lo que vemos son como sombras en una caverna; lo verdaderamente real son las Ideas.", "opts": [{"k": "bueno", "t": "Si las Ideas están separadas de las cosas, ¿cómo explican lo que ocurre aquí? Una Idea eterna e inmóvil no explica por qué una flor nace, crece y se marchita.", "r": "Mi alumno Aristóteles me discute eso mismo en la Academia. Yo digo que las cosas «participan» de las Ideas. Pero reconozco que esa palabra necesita más explicación de la que le he dado.", "why": "Planteas la objeción de la separación, que Aristóteles hizo a la teoría de las Ideas: si están aparte, no explican el cambio.", "f": ""}, {"k": "flojo", "t": "Pero yo toco esta mesa y es real, no es ninguna sombra.", "r": "No digo que la mesa no exista: digo que es menos real que aquello que la hace ser mesa. Tocar no es entender.", "why": "Apelas a lo que sientes con las manos, que es justo lo que Platón pone en cuestión: no respondes a su razón.", "f": ""}, {"k": "falacia", "t": "Casi nadie cree en un mundo de Ideas; si fuera verdad, lo creería más gente.", "r": "También los prisioneros de la caverna eran mayoría, y se habrían reído del que volvió de la luz. Hasta habrían querido matarlo.", "why": "Que pocos crean algo no lo hace falso, ni que muchos lo crean lo hace verdadero.", "f": "Apelación a la mayoría"}]}, {"say": "Nunca has visto dos palos perfectamente iguales y, sin embargo, sabes qué es la igualdad perfecta. Ese saber no viene de los ojos: el alma lo recuerda, porque contempló las Ideas antes de nacer.", "opts": [{"k": "bueno", "t": "Quizás no lo recuerdo: lo formo yo. Comparo muchas cosas parecidas, me quedo con lo que tienen en común y lo perfecciono con el pensamiento. Eso es abstraer, no recordar.", "r": "Para notar que dos palos no son del todo iguales ya necesitas tener la Igualdad en la mente: ¿cómo comparas con algo que aún no tienes? Pero tu respuesta es la que darán mi discípulo y muchos después. Es seria.", "why": "Opones la abstracción a la reminiscencia: es la respuesta de Aristóteles y, siglos después, de los empiristas.", "f": ""}, {"k": "flojo", "t": "Yo no recuerdo nada de antes de nacer.", "r": "Claro, por eso aprender cuesta. Recordar no es ver imágenes de otra vida: es reconocer lo que ya sabías, como el joven esclavo de Menón descubrió la geometría solo con preguntas.", "why": "Confundes la reminiscencia con tener recuerdos conscientes: no tocas el argumento.", "f": ""}, {"k": "falacia", "t": "Me da miedo pensar que el alma muere con el cuerpo, así que tiene que ser inmortal.", "r": "Yo también deseo que lo sea, pero desearlo no lo prueba. En el Fedón, los amigos de Sócrates le piden que les quite ese miedo de niño al coco, y él responde con razones, no con deseos.", "why": "Tu miedo no es una razón: lo que sientes no decide lo que es verdad.", "f": "Apelación a la emoción"}]}, {"say": "Hay una Idea para cada grupo de cosas que llamamos con el mismo nombre: muchas cosas bellas, una sola Belleza; muchas camas, una sola Idea de cama.", "opts": [{"k": "bueno", "t": "Si las cosas grandes lo son porque se parecen a la Idea de lo Grande, entonces las cosas y la Idea comparten algo. Haría falta otra Idea para explicar ese parecido, y otra más, sin fin.", "r": "Es el argumento que pongo en boca del viejo Parménides en uno de mis diálogos. Lo llaman el «tercer hombre», y no lo he resuelto del todo. Quizás la Idea no es una cosa grande más, sino el modelo. Pero me obligas a pensarlo mejor.", "why": "Planteas el argumento del tercer hombre, que Platón discute en el Parménides y que Aristóteles repetirá.", "f": ""}, {"k": "flojo", "t": "Pero las palabras las inventamos nosotros: en otro idioma la belleza se dice de otra forma.", "r": "Cambia la palabra, no lo que la palabra nombra. Un griego y un persa pueden ver la misma belleza aunque la llamen distinto.", "why": "Confundes el nombre con lo nombrado: que cambie el idioma no afecta al argumento.", "f": ""}, {"k": "falacia", "t": "O sea, que crees que hay un cielo lleno de camas y mesas flotando. ¡Qué tontería!", "r": "Hablé de un lugar más allá del cielo, sí, pero como imagen. Las Ideas no son muebles que floten en ninguna parte: no se ven con los ojos, se comprenden con la inteligencia.", "why": "Deformas la teoría para hacerla ridícula y atacarla con facilidad.", "f": "Hombre de paja"}]}, {"say": "El que sale de la caverna y ve el Sol, que es el Bien, debe volver a bajar para gobernar a los demás. Mientras los filósofos no sean reyes, no tendrán fin los males de las ciudades.", "opts": [{"k": "bueno", "t": "Aunque alguien conociera el Bien, ¿quién lo vigila si gobierna sin control? Quizás la pregunta no sea quién debe mandar, sino cómo organizar la ciudad para que un mal gobernante haga el menor daño posible.", "r": "Por eso prohibí a mis guardianes tener oro y casas propias: que no ganen nada mandando. Y ya anciano, en las Leyes, puse la ley por encima de quien gobierna. Tu pregunta me acompañó toda la vida.", "why": "Es la objeción de Karl Popper: importa más poder controlar al poder que encontrar al gobernante perfecto.", "f": ""}, {"k": "flojo", "t": "A mí no me gustaría que me gobernara un filósofo.", "r": "Tampoco al enfermo le gusta la medicina amarga. No pregunto qué te gusta, sino quién sabe gobernar mejor, como preguntaríamos quién sabe pilotar un barco.", "why": "Respondes con un gusto personal, no con una razón.", "f": ""}, {"k": "falacia", "t": "Tienes razón: o gobiernan los sabios, o gobierna la masa ignorante. No hay otra opción.", "r": "Me das la razón con una trampa. Yo mismo describo muchas formas de gobierno, y en las Leyes defendí una mezcla de monarquía y democracia.", "why": "Reduces todas las posibilidades a dos, como si no hubiera formas intermedias.", "f": "Falso dilema"}]}], "fin": {"alto": "Has subido por la cuesta de la caverna sin soltar la razón, y hasta me has hecho dudar de mis Ideas. Eso es dialéctica: buscar juntos la verdad.", "medio": "Empiezas a girar la cabeza hacia la luz, pero aún confundes a veces las sombras con las cosas. Sigue subiendo.", "bajo": "Sigues mirando la pared de la caverna y discutiendo sobre sombras. Date la vuelta: la luz molesta al principio, pero libera."}},
  {"id": "aristoteles", "q": "¿Qué es una vida feliz?", "rounds": [{"say": "Todos buscamos la felicidad por sí misma, y lo demás por ella. Y ser feliz es realizar bien lo que es propio del ser humano: vivir según la razón y la virtud.", "opts": [{"k": "bueno", "t": "Que la razón sea lo propio del ser humano no prueba que sea lo mejor para él. Lo que nos distingue de los animales no tiene por qué ser lo que nos hace felices.", "r": "Lo propio de cada cosa es su obra: el buen flautista es el que toca bien la flauta. Pero admito que pasar de «lo propio» a «lo mejor» necesita más argumentos de los que di.", "why": "Cuestionas el «argumento de la función»: que algo sea exclusivo del ser humano no prueba que sea su bien.", "f": ""}, {"k": "flojo", "t": "Para mí la felicidad es estar contento.", "r": "¿Contento con qué? Un niño está contento con un juguete, y no diríamos que ha logrado una buena vida. La felicidad abarca una vida entera: una golondrina no hace verano.", "why": "Das una definición vaga que no distingue un buen momento de una buena vida.", "f": ""}, {"k": "falacia", "t": "La mayoría de la gente cree que ser feliz es tener dinero y placeres, así que eso es la felicidad.", "r": "Ya lo dije: la mayoría elige la vida de los placeres, una vida propia de animales. Y el dinero es solo un medio: nadie lo quiere por sí mismo.", "why": "Que muchos crean algo no lo hace verdadero.", "f": "Apelación a la mayoría"}]}, {"say": "La virtud es un término medio entre dos vicios: el valor está entre la cobardía y la temeridad; la generosidad, entre la tacañería y el derroche.", "opts": [{"k": "bueno", "t": "El término medio no sirve para todo: ¿cuál es el término medio del asesinato? Y, además, la regla no me dice dónde está el medio en cada caso concreto.", "r": "Ya advertí que el asesinato o el robo no tienen término medio: son malos en sí. Y el medio lo fija el hombre prudente, no una fórmula. Admito que eso exige tener ya prudencia para encontrarlo.", "why": "Señalas los límites de la doctrina del término medio, que el propio Aristóteles tuvo que reconocer.", "f": ""}, {"k": "flojo", "t": "Entonces hay que ser siempre moderado: ni mucho ni poco.", "r": "No. El medio no es la mitad exacta: ante una gran injusticia, lo justo es enfadarse mucho. El medio depende de nosotros y de la situación.", "why": "Confundes el término medio con la tibieza: es un malentendido frecuente.", "f": ""}, {"k": "falacia", "t": "Conozco a un chico valiente que acabó metido en problemas por arriesgarse; así que el valor siempre trae problemas.", "r": "Un caso no hace una regla. Y quizá tu amigo no era valiente, sino temerario: el que se arriesga sin medida ni motivo.", "why": "Sacas una conclusión general de un solo caso.", "f": "Generalización apresurada"}]}, {"say": "Por naturaleza, unos nacen para mandar y otros para obedecer, como el alma manda sobre el cuerpo. Por eso hay quienes son esclavos por naturaleza.", "opts": [{"k": "bueno", "t": "Tú mismo reconoces que muchos son esclavos solo porque perdieron una guerra, y que la naturaleza a menudo no distingue a los libres de los esclavos. Entonces, ¿cómo sabes quién nació para obedecer?", "r": "Es cierto que distingo la esclavitud por naturaleza de la que nace de la guerra, y que esta es muy discutida. Me obligas a ver que la línea que trazo no es tan clara como creía.", "why": "Usas las propias distinciones de Aristóteles contra su defensa de la esclavitud natural, que hoy se considera su error más grave.", "f": ""}, {"k": "flojo", "t": "Pero tener esclavos está prohibido.", "r": "En mi Atenas no lo está. Que una ley lo prohíba o lo permita no dice si es justo por naturaleza: eso es lo que discutimos.", "why": "Mencionas una ley de tu época, pero la pregunta es si hay razones, no qué dice la ley.", "f": ""}, {"k": "falacia", "t": "Siempre ha habido esclavos en todas las ciudades, así que debe de ser algo natural.", "r": "No me ayudas: que algo se haya hecho siempre no prueba que sea natural. Yo intento dar razones, y tú solo me das costumbres.", "why": "Que algo se haya hecho siempre no demuestra que sea correcto ni natural.", "f": "Apelación a la tradición"}]}, {"say": "La vida más feliz es la contemplativa: pensar es lo más divino que hay en nosotros, y es la actividad que más se basta a sí misma.", "opts": [{"k": "bueno", "t": "Pero tú mismo dices que somos animales políticos y que nadie elegiría vivir sin amigos. Una vida dedicada solo a pensar olvida la amistad y la ciudad, que también forman parte de la felicidad.", "r": "Tocas una tensión que mis lectores discuten desde hace siglos. El sabio también necesita amigos y vive con otros; la contemplación es lo más alto, no lo único. Pero me obligas a unir mejor las dos partes de mi ética.", "why": "Detectas la tensión entre la vida contemplativa y la vida política en la Ética a Nicómaco, un debate clásico entre sus intérpretes.", "f": ""}, {"k": "flojo", "t": "Pensar todo el día debe de ser aburridísimo.", "r": "Para ti, quizá. Pero pregunta a quien acaba de resolver un problema difícil si se aburrió. El placer de pensar es de los más puros y duraderos.", "why": "Opones una impresión personal a un argumento.", "f": ""}, {"k": "falacia", "t": "O pasas la vida pensando, o la pasas divirtiéndote; como pensar no es divertido, la felicidad es divertirse.", "r": "Hay más vidas que esas dos: la del buen ciudadano, la del buen amigo. Y sería absurdo trabajar y sufrir toda la vida solo para divertirse.", "why": "Presentas solo dos opciones cuando hay muchas más.", "f": "Falso dilema"}]}], "fin": {"alto": "Has razonado con prudencia, buscando el término medio entre aceptarlo todo y rechazarlo todo. Serías un buen ciudadano de cualquier ciudad.", "medio": "Vas por buen camino, pero la virtud es un hábito: nos hacemos citaristas tocando la cítara, y buenos razonadores razonando.", "bajo": "Te dejaste llevar por la opinión de muchos y por atajos. Recuerda: una golondrina no hace verano, y un buen argumento no se improvisa."}},
  {"id": "epicuro", "q": "¿Es el placer lo único bueno?", "rounds": [{"say": "El placer es el principio y el fin de la vida feliz. Pero no hablo de los placeres de los glotones: hablo de no sufrir en el cuerpo y no estar turbado en el alma.", "opts": [{"k": "bueno", "t": "Si el mayor placer es no sufrir, una persona dormida sin sueños estaría en el estado perfecto. No sentir dolor no parece lo mismo que sentir alegría.", "r": "No hablo de no sentir, sino de sentir la vida sin dolor: un cuerpo sano y una mente serena se disfrutan. Cicerón me reprochará esa misma confusión, y admito que debo distinguir mejor la calma de la indiferencia.", "why": "Es la objeción clásica de Cicerón: la ausencia de dolor no parece lo mismo que el placer.", "f": ""}, {"k": "flojo", "t": "Pero hay cosas buenas que duelen, como estudiar para un examen.", "r": "De acuerdo: a veces elijo un dolor porque trae un placer mayor. Eso no contradice lo que digo; lo confirma.", "why": "Tu ejemplo ya lo explica Epicuro, que calcula placeres y dolores a largo plazo.", "f": ""}, {"k": "falacia", "t": "En Atenas decían que en tu Jardín hacíais fiestas sin control: no se puede hacer caso a alguien así.", "r": "Eso decían mis enemigos, y mentían: en el Jardín bebíamos agua y comíamos pan. Pero aunque fuera verdad, tendrías que refutar mi argumento, no mi fama.", "why": "Atacas a la persona con rumores en lugar de discutir su idea.", "f": "Ataque a la persona"}]}, {"say": "La muerte no es nada para nosotros: mientras existimos, la muerte no está, y cuando la muerte está, nosotros ya no existimos.", "opts": [{"k": "bueno", "t": "La muerte puede ser mala aunque no la sintamos, porque nos quita todo lo bueno que habríamos vivido. A alguien pueden hacerle daño sin que se entere, como cuando lo traicionan a sus espaldas.", "r": "Dices que la muerte nos priva de bienes. Yo respondo que no queda nadie a quien le falten. Pero tu ejemplo de la traición me inquieta: quizás no todo daño necesita ser sentido.", "why": "Es el argumento de la privación, que defendió Thomas Nagel: algo puede ser malo para alguien aunque no lo sienta.", "f": ""}, {"k": "flojo", "t": "Pero a mí me da pena cuando alguien muere.", "r": "Es natural echar de menos a un amigo. Pero yo hablo del miedo a la propia muerte, no del dolor de perder a otros.", "why": "Hablas de otra cosa: el duelo por los demás no es el miedo a la propia muerte.", "f": ""}, {"k": "falacia", "t": "Piensa en lo triste que es imaginar que todo se acaba: la muerte tiene que ser terrible.", "r": "Me pides que tenga miedo para darte la razón. Al imaginarla te ves ahí, mirando, y justo eso es lo que no ocurrirá.", "why": "Usas un sentimiento intenso en lugar de una razón.", "f": "Apelación a la emoción"}]}, {"say": "Los dioses existen, pero son felices e imperturbables: no se ocupan de nosotros ni castigan a nadie. No hay que temerlos.", "opts": [{"k": "bueno", "t": "Si los dioses no hacen nada en el mundo y tu física de átomos lo explica todo sin ellos, ¿qué razones quedan para decir que existen?", "r": "Digo que todos los pueblos tienen una idea de ellos que llega a nuestra mente. Pero sé que algunos me acusaron de ser un ateo disimulado. Tocas un punto débil.", "why": "Es la sospecha que expresaron Cicerón y Posidonio: si los dioses no actúan, sobran en la explicación.", "f": ""}, {"k": "flojo", "t": "Yo no sé si hay dioses o no.", "r": "Es honrado dudar. Pero lo importante de mi argumento es otra cosa: aunque existan, no tienes por qué temerlos.", "why": "Expresas una duda, pero no respondes a la tesis.", "f": ""}, {"k": "falacia", "t": "Cuando la ciudad olvida los sacrificios, luego llegan sequías y desgracias: eso prueba que los dioses castigan.", "r": "Las sequías tienen causas naturales: los vientos, las nubes, el movimiento de los átomos. Que una cosa venga después de otra no significa que la cause.", "why": "Confundes que algo ocurra después con que ocurra por eso.", "f": "Falsa causa"}]}, {"say": "De todo lo que la sabiduría nos da para ser felices, lo más grande es la amistad. Por eso es mejor vivir retirado, en el Jardín con los amigos, lejos de la política.", "opts": [{"k": "bueno", "t": "Si todos los sabios se retiran a su jardín, la ciudad queda en manos de los peores. Y tu tranquilidad depende de unas leyes y de una paz que otros tienen que cuidar.", "r": "Plutarco escribirá un libro entero contra mi «vive oculto». Yo digo que el sabio no se mete en política salvo que algo lo obligue. Pero tienes razón: mi jardín necesita una ciudad en paz.", "why": "Es la crítica clásica de estoicos y de Plutarco: retirarse de la vida pública deja lo común en peores manos.", "f": ""}, {"k": "flojo", "t": "Pero los amigos a veces te fallan.", "r": "A veces, sí. Pero lo que más nos ayuda no es tanto la ayuda de los amigos como la confianza en que nos ayudarán.", "why": "Señalas un riesgo real, pero no discutes ni el valor de la amistad ni la retirada de la política.", "f": ""}, {"k": "falacia", "t": "Platón y Aristóteles dicen que hay que participar en la ciudad, y son más famosos que tú, así que te equivocas.", "r": "Muchos los admiran, pero la fama de un filósofo no es un argumento. Dime qué razones dan, y las discutiremos.", "why": "La fama de quien defiende una idea no decide si es verdadera.", "f": "Apelación a la autoridad"}]}], "fin": {"alto": "Has discutido sin miedo y sin prisa, como se conversa entre amigos en el Jardín. Esa calma al pensar ya es una forma de felicidad.", "medio": "Mezclas buenas razones con otras flojas. Elige tus argumentos como eliges tus placeres: con cálculo.", "bajo": "Te dejaste llevar por el miedo y los rumores. Recuerda: los dioses no son de temer, la muerte no es nada, el bien es fácil de conseguir y el dolor, fácil de soportar."}},
  {"id": "hobbes", "q": "¿Necesitamos un poder fuerte para vivir en paz?", "rounds": [{"say": "Sin un poder común que nos tenga a raya, viviríamos en guerra de todos contra todos, y la vida sería solitaria, pobre, desagradable, brutal y corta.", "opts": [{"k": "bueno", "t": "Nunca hubo un estado así: los seres humanos siempre hemos vivido en familias y grupos que cooperan. Partes de un individuo aislado que no ha existido nunca.", "r": "Quizás nunca fue así en todo el mundo, lo admito. Pero mira a los reyes, siempre armados unos frente a otros, o a un país en guerra civil: ahí ves lo que pasa cuando falta un poder común.", "why": "Cuestionas que el estado de naturaleza haya sido real, una objeción clásica que se le hizo a Hobbes.", "f": ""}, {"k": "flojo", "t": "Yo no me pelearía con nadie aunque no hubiera policía.", "r": "Quizás. Pero ¿cierras tu casa con llave cuando sales? Con ese gesto acusas a tus vecinos tanto como yo con mis palabras.", "why": "Hablas de ti, pero Hobbes argumenta sobre lo que pasa cuando nadie puede fiarse de nadie.", "f": ""}, {"k": "falacia", "t": "Dices eso porque eres un miedoso: tú mismo contaste que naciste con el miedo como hermano gemelo.", "r": "Es verdad que lo escribí: mi madre dio a luz gemelos, a mí y al miedo. Pero que yo sea miedoso no hace falso mi argumento.", "why": "Atacas el carácter de quien habla en lugar de su razonamiento.", "f": "Ataque a la persona"}]}, {"say": "Por eso hacemos un pacto: cada uno entrega su derecho a gobernarse a un soberano, el Leviatán, que tendrá todo el poder para mantener la paz.", "opts": [{"k": "bueno", "t": "Si tememos tanto a los demás, ¿por qué no íbamos a temer a un soberano con todo el poder? Es como protegerse de los zorros entregándose a un león.", "r": "Locke dirá eso mismo de los zorros y el león. Respondo que el peor soberano es menos terrible que la guerra civil. Pero reconozco que confiamos mucho en que el león no tenga hambre.", "why": "Es la famosa objeción de Locke: quien huye de los zorros no debería entregarse a un león.", "f": ""}, {"k": "flojo", "t": "Prefiero que gobiernen muchos y no uno solo.", "r": "Puede ser una asamblea, no tiene por qué ser un rey. Lo que importa es que su poder no esté dividido.", "why": "Hablas de cuántos gobiernan, pero Hobbes discute cuánto poder debe tener el soberano, sea uno o muchos.", "f": ""}, {"k": "falacia", "t": "Si le das poder a un soberano, empezará cobrando impuestos, luego nos quitará las casas y acabará encerrándonos a todos.", "r": "Te saltas todos los pasos. Un soberano sensato sabe que su fuerza depende de la de sus súbditos: arruinarlos es arruinarse.", "why": "Encadenas consecuencias extremas sin justificar cada paso.", "f": "Pendiente resbaladiza"}]}, {"say": "Antes del pacto no hay justicia ni injusticia: donde no hay poder común, no hay ley, y donde no hay ley, no hay injusticia.", "opts": [{"k": "bueno", "t": "Pero el pacto solo funciona si ya es obligatorio cumplir lo prometido. Esa norma tiene que existir antes que el soberano: no la puede crear él.", "r": "Las llamo leyes de naturaleza: buscar la paz, cumplir los pactos. Son dictados de la razón anteriores al Estado. Pero sin un poder que las haga cumplir, nadie se arriesga a obedecerlas. Me obligas a precisar.", "why": "Señalas que la teoría de Hobbes necesita normas previas al soberano: sus propias «leyes de naturaleza».", "f": ""}, {"k": "flojo", "t": "A mí no me gusta que me digan lo que tengo que hacer.", "r": "A nadie le gusta. Pero mira lo que ocurre donde nadie manda: cada uno hace lo que quiere, y por eso nadie está seguro.", "why": "Expresas un sentimiento, no un argumento sobre la justicia.", "f": ""}, {"k": "falacia", "t": "Claro: lo que manda el soberano es justo porque es él quien decide qué es justo.", "r": "Me das la razón dando vueltas en círculo. Mi argumento parte de otra cosa: de lo que pasa cuando no hay un poder común.", "why": "La conclusión ya está escondida en la premisa.", "f": "Petición de principio"}]}, {"say": "Los súbditos deben obedecer al soberano, porque cualquier rebelión nos devuelve a la guerra de todos contra todos.", "opts": [{"k": "bueno", "t": "Pero tú mismo admites que nadie puede renunciar a defender su vida: si el soberano quiere matarme, puedo resistirme. Y si ya no puede protegerme, ¿por qué seguir obedeciéndole?", "r": "Tienes razón: la obligación de los súbditos dura lo que dura el poder que los protege, y nadie renuncia al derecho a defender su vida. Has leído mi Leviatán con atención.", "why": "Usas los límites que el propio Hobbes pone a la obediencia: el derecho a la vida y el deber de protección.", "f": ""}, {"k": "flojo", "t": "Algunas rebeliones salieron bien.", "r": "¿Y cuántas acabaron en matanzas? Yo vi a mi país en guerra civil. Una rebelión es una lotería en la que se apuesta la vida de todos.", "why": "Lo mencionas, pero no dices cuáles ni por qué eso cambiaría la regla.", "f": ""}, {"k": "falacia", "t": "Hoy la mayoría de la gente vive en democracias, así que tu idea está equivocada.", "r": "Que muchos vivan de una forma no prueba que sea la mejor. Dame una razón, no un recuento.", "why": "Que algo sea mayoritario no lo hace correcto.", "f": "Apelación a la mayoría"}]}], "fin": {"alto": "Has discutido sin miedo y con argumentos. Contigo, el estado de naturaleza duraría muy poco.", "medio": "Algunos argumentos tuyos son sólidos; otros, solo ruido. Recuerda: las palabras son las fichas con que cuentan los sabios, pero la moneda de los necios.", "bajo": "Usaste insultos y miedos en lugar de razones. Así empiezan las guerras: cuando nadie escucha."}},
  {"id": "rousseau", "q": "¿Nos corrompe la sociedad?", "rounds": [{"say": "Todo está bien al salir de las manos del Autor de las cosas; todo degenera entre las manos del hombre. En estado de naturaleza éramos buenos: nos movían el amor de sí y la piedad.", "opts": [{"k": "bueno", "t": "Si éramos buenos, ¿de dónde salió la sociedad que nos corrompe? La hicieron seres humanos: algo de lo malo tenía que estar ya en nosotros.", "r": "No había maldad, había una capacidad: la perfectibilidad, que nos permite cambiar para bien y para mal. Las circunstancias nos hicieron depender unos de otros. Pero admito que tu pregunta es la más difícil para mí.", "why": "Planteas la pregunta clásica a Rousseau: si la sociedad corrompe, ¿qué hay en nosotros que la hizo posible?", "f": ""}, {"k": "flojo", "t": "Pero hoy vivimos mejor que en las cavernas.", "r": "Vivimos más cómodos, no más felices ni mejores. Las comodidades se vuelven necesidades, y las necesidades, cadenas.", "why": "Hablas de comodidad, pero Rousseau habla de bondad y de felicidad.", "f": ""}, {"k": "falacia", "t": "Abandonaste a tus cinco hijos en un hospicio: no puedes darnos lecciones sobre la bondad.", "r": "Es lo más vergonzoso de mi vida, y lo confesé. Pero si mis ideas son falsas, demuéstralo con razones, no con mis faltas.", "why": "Aunque su conducta fuera reprochable, eso no refuta su argumento.", "f": "Ataque a la persona"}]}, {"say": "El primero que cercó un terreno, dijo «esto es mío» y encontró gente lo bastante simple para creerle fue el verdadero fundador de la sociedad civil. De ahí vinieron crímenes, guerras y miserias.", "opts": [{"k": "bueno", "t": "La propiedad también tiene ventajas: quien cultiva una tierra que es suya la cuida y la mejora. Sin ella, ¿quién plantaría un árbol que dará fruto dentro de diez años?", "r": "Reconozco que con la tierra cultivada llegaron el trabajo y las artes. Y en el Contrato no pido abolir la propiedad: pido que nadie sea tan rico como para comprar a otro, ni tan pobre como para venderse. Me ayudas a precisar.", "why": "Recuerdas el argumento clásico, de Aristóteles a Locke, de que la propiedad estimula el cuidado y el trabajo.", "f": ""}, {"k": "flojo", "t": "A mí me gusta tener mis cosas.", "r": "Claro, a todos. Pero no hablo de tus cosas, sino de cuando unos tienen tanto que los demás no tienen nada.", "why": "Respondes con una preferencia personal, no con un argumento.", "f": ""}, {"k": "falacia", "t": "O sea, que quieres que volvamos a vivir en el bosque a cuatro patas.", "r": "Voltaire se burló así de mí: dijo que al leerme daban ganas de andar a cuatro patas. Pero nunca propuse volver al bosque con los osos; eso ya no es posible. Propongo una sociedad más justa.", "why": "Deformas la tesis para ridiculizarla: Rousseau no propone volver al estado de naturaleza.", "f": "Hombre de paja"}]}, {"say": "La solución es el contrato social: cada uno se entrega a la voluntad general y, al obedecer la ley que se da a sí mismo, sigue siendo libre.", "opts": [{"k": "bueno", "t": "Si la mayoría vota algo, ¿cómo sé que es la voluntad general y no solo lo que quieren los más? Y si no estoy de acuerdo, ¿soy libre obedeciendo una ley que rechazo?", "r": "Distingo la voluntad general de la voluntad de todos, que es solo una suma de intereses. Y dije, lo sé, que a quien se niegue se le obligará a ser libre. Esa frase me la han reprochado mucho, y entiendo por qué.", "why": "Señalas lo difícil que es distinguir la voluntad general de la mayoría, y lo inquietante de «obligar a ser libre».", "f": ""}, {"k": "flojo", "t": "Yo prefiero hacer lo que me dé la gana.", "r": "Eso es la libertad natural, la del que solo sigue su impulso. El impulso del apetito es esclavitud; obedecer la ley que uno mismo se ha dado es libertad.", "why": "Confundes libertad y capricho: Rousseau distingue la libertad natural de la libertad civil y moral.", "f": ""}, {"k": "falacia", "t": "Después de tu libro llegó la Revolución, con el Terror; así que tu libro causó el Terror.", "r": "No puedo saber qué harán con mis libros cuando yo no esté. Pero que algo venga después de otra cosa no significa que la cause: una revolución tiene muchas causas.", "why": "Confundes que algo ocurra después con que ocurra por eso.", "f": "Falsa causa"}]}, {"say": "La educación debe seguir a la naturaleza: que el niño aprenda por la experiencia, no con libros ni sermones. A los doce años, mi Emilio apenas sabrá qué es un libro, y no importa.", "opts": [{"k": "bueno", "t": "Pero el tutor de tu Emilio lo prepara todo a escondidas para que aprenda lo que él quiere. Eso no es libertad: es una forma de control más sutil.", "r": "Lo escribí: no hay sujeción más perfecta que la que conserva la apariencia de libertad. Yo lo veía como un método; tú me haces ver que también es un poder. Tu objeción es justa.", "why": "Detectas la paradoja del Emilio: el tutor controla todo el entorno del niño mientras le hace creer que es libre.", "f": ""}, {"k": "flojo", "t": "Me encantaría no ir a la escuela.", "r": "No te creas: mi Emilio trabaja mucho, observa, construye y aprende un oficio. No es un niño sin educación, sino con otra educación.", "why": "Hablas de tu deseo, no de las razones del método.", "f": ""}, {"k": "falacia", "t": "Siempre se ha educado con libros y maestros, así que es la única forma correcta.", "r": "Durante siglos se ha tratado a los niños como adultos pequeños, a fuerza de castigos. Que se haya hecho siempre no prueba que esté bien.", "why": "Que algo se haya hecho siempre no lo hace correcto.", "f": "Apelación a la tradición"}]}], "fin": {"alto": "Has pensado con libertad y con sentido de la justicia. Si todos razonaran así, la voluntad general hablaría claro.", "medio": "Tienes buenas intuiciones, pero a veces te dejas llevar por lo que piensan otros. El hombre social solo sabe vivir en la opinión ajena: aprende a juzgar por ti.", "bajo": "Repetiste prejuicios y burlas. La sociedad te ha enseñado a aparentar; ahora aprende a pensar."}},
  {"id": "hume", "q": "¿Podemos conocer las causas de las cosas?", "rounds": [{"say": "Todas nuestras ideas vienen de impresiones: de lo que sentimos y percibimos. Si no puedes señalar de qué impresión viene una idea, sospecha que es una palabra vacía.", "opts": [{"k": "bueno", "t": "Tú mismo planteas el caso del tono de azul: alguien que ha visto todos los azules menos uno podría imaginar el que falta sin haber tenido nunca esa impresión.", "r": "Lo reconocí: el tono de azul que falta. Dije que era un caso tan raro que no merecía cambiar la regla general. Pero un contraejemplo es un contraejemplo, y has sabido encontrarlo.", "why": "Usas el famoso «tono de azul que falta», el contraejemplo que el propio Hume planteó contra su principio.", "f": ""}, {"k": "flojo", "t": "Yo tengo la idea de un dragón y nunca he visto uno.", "r": "Un dragón es una serpiente, unas alas y un fuego que has visto por separado. La mente combina, pero no crea de la nada.", "why": "Tu ejemplo ya lo explica Hume: las ideas complejas se forman combinando otras simples.", "f": ""}, {"k": "falacia", "t": "Descartes dice que tenemos ideas innatas, y Descartes era un genio.", "r": "Ser un genio no libra a nadie de equivocarse. Dime qué idea concreta crees que no viene de ninguna impresión, y la examinaremos.", "why": "Que alguien famoso lo diga no basta: hacen falta razones.", "f": "Apelación a la autoridad"}]}, {"say": "Nunca vemos la causa: vemos que una bola golpea a otra y que la segunda se mueve. Lo que llamamos «causa» es la costumbre de ver una cosa seguida de otra.", "opts": [{"k": "bueno", "t": "Si la causalidad fuera solo costumbre, la ciencia no tendría leyes necesarias. Quizás la causa no viene de la experiencia, sino que es una forma en que nuestra mente ordena toda experiencia.", "r": "Kant dirá que yo lo desperté de su sueño dogmático, y propondrá justo eso. Es una salida ingeniosa, aunque me pregunto cómo sabe que la mente funcionará siempre así.", "why": "Es la respuesta de Kant: la causalidad sería una condición de la experiencia, no algo aprendido de ella.", "f": ""}, {"k": "flojo", "t": "Pero si suelto un vaso, se rompe: está claro que la caída lo rompe.", "r": "Lo esperas, y haces bien en esperarlo. Pero lo que has visto es que siempre ha pasado; la necesidad la pone tu costumbre, no tus ojos.", "why": "Repites justo el tipo de experiencia que Hume analiza, sin responder a su argumento.", "f": ""}, {"k": "falacia", "t": "Si no podemos ver las causas, no podremos saber nada, nadie se fiará de los médicos y la sociedad se hundirá.", "r": "Yo me sigo fiando de los médicos, y de que el pan alimenta. La costumbre es la gran guía de la vida humana: dudar en el estudio no me impide vivir.", "why": "Encadenas consecuencias extremas que no se siguen de la tesis.", "f": "Pendiente resbaladiza"}]}, {"say": "Que el Sol haya salido todos los días no demuestra que saldrá mañana. Suponer que el futuro se parecerá al pasado no tiene una justificación racional.", "opts": [{"k": "bueno", "t": "Quizás no se pueda demostrar, pero fiarse del pasado es la mejor apuesta: si la naturaleza tiene regularidades, la inducción las encontrará; si no las tiene, ningún método lo hará.", "r": "Reichenbach llamará a eso una justificación pragmática. No demuestra que el Sol saldrá, pero muestra que fiarse del pasado no es absurdo. Acepto el trato: yo tampoco dejo de comer pan.", "why": "Es la «justificación pragmática» de la inducción que propuso Hans Reichenbach.", "f": ""}, {"k": "flojo", "t": "Los científicos saben por qué sale el Sol: porque la Tierra gira.", "r": "Muy bien. ¿Y cómo sabes que la Tierra seguirá girando mañana? Solo has movido el problema un paso más allá.", "why": "Una explicación científica también supone que la naturaleza seguirá igual: no resuelve el problema.", "f": ""}, {"k": "falacia", "t": "La inducción funciona porque siempre ha funcionado.", "r": "Eso es usar la inducción para probar la inducción: das por supuesto lo que querías demostrar.", "why": "Justificas la inducción con la propia inducción: es el círculo que Hume denunció.", "f": "Petición de principio"}]}, {"say": "La razón es, y debe ser, esclava de las pasiones. Nos dice cómo conseguir lo que queremos, pero nunca qué debemos querer.", "opts": [{"k": "bueno", "t": "Pero la razón puede cambiar lo que deseo: si descubro que algo que quería me hará daño, el deseo cede. La razón no manda, pero tampoco es tan esclava.", "r": "Admito que, si un deseo se apoya en una creencia falsa, al corregirla el deseo cede. Pero entonces la razón solo informa: la fuerza sigue viniendo de otra pasión. Me obligas a precisar qué significa «esclava».", "why": "Muestras que la razón influye en el deseo al corregir creencias, algo que el propio Hume admite.", "f": ""}, {"k": "flojo", "t": "Yo siempre pienso antes de actuar.", "r": "Piensas cómo conseguir lo que quieres. Pero ¿alguna vez has decidido, solo pensando, qué querer?", "why": "Describes una costumbre tuya, pero no tocas la tesis sobre de dónde viene la motivación.", "f": ""}, {"k": "falacia", "t": "Mi hermano siempre actúa por impulso y se equivoca, así que las pasiones siempre nos llevan al error.", "r": "Tu hermano no es la humanidad. Y las pasiones también nos mueven a la compasión, a la amistad y a la justicia.", "why": "Sacas una regla general de un solo caso.", "f": "Generalización apresurada"}]}], "fin": {"alto": "Has dudado con moderación y argumentado con cuidado: un escepticismo sensato. Ahora, como yo, puedes ir a cenar y a jugar una partida con tus amigos.", "medio": "Algunas de tus razones son sólidas; otras, pura costumbre. El sabio ajusta su creencia a la evidencia.", "bajo": "Te fiaste de autoridades y de miedos. Si un libro no contiene razonamientos ni experiencia, arrójalo al fuego… y haz lo mismo con los malos argumentos."}},
  {"id": "marx", "q": "¿La economía decide cómo pensamos?", "rounds": [{"say": "No es la conciencia de los hombres la que determina su ser, sino su ser social el que determina su conciencia. Dime cómo produce una sociedad y te diré cómo piensa.", "opts": [{"k": "bueno", "t": "Las ideas también cambian la economía: una religión, un invento o una teoría científica pueden transformar la forma de producir. La relación va en las dos direcciones.", "r": "Engels explicará que la economía decide solo «en última instancia» y que las ideas también actúan sobre ella. Insistimos tanto en lo económico porque discutíamos con quienes lo olvidaban. Tu objeción es justa.", "why": "Es la objeción de Max Weber: las ideas también mueven la economía, algo que el propio Engels tuvo que matizar.", "f": ""}, {"k": "flojo", "t": "Yo pienso lo que quiero: nadie decide por mí.", "r": "Eso cree todo el mundo. Pero ¿por qué piensas que tener éxito es tener cosas? ¿Lo elegiste tú, o lo aprendiste del mundo en que vives?", "why": "Afirmas tu independencia sin argumentar, justo lo que Marx pone en duda.", "f": ""}, {"k": "falacia", "t": "Vivías del dinero de Engels, que tenía una fábrica: eres un hipócrita.", "r": "Es cierto que Engels me ayudó, y que trabajaba en la fábrica de su familia. Pero si mi análisis es falso, demuéstralo con datos y razones, no con mi cuenta del banco.", "why": "Criticas la vida de quien habla en lugar de su análisis.", "f": "Ataque a la persona"}]}, {"say": "En la fábrica, el obrero está alienado: lo que produce no le pertenece, su trabajo es forzado, y solo se siente libre fuera de él, cuando come, bebe o está en su casa.", "opts": [{"k": "bueno", "t": "Pero muchos trabajos son monótonos sea quien sea el dueño: una cadena de montaje del Estado sería igual de alienante. Quizás el problema no es solo quién posee la fábrica, sino cómo es el trabajo.", "r": "También critico la división del trabajo, que convierte al obrero en un apéndice de la máquina. Cambiar de dueño no basta si no cambia el trabajo mismo. Me haces ver que la crítica tiene que llegar más hondo.", "why": "Distingues la propiedad de la fábrica de la organización del trabajo, algo que mostraron las economías socialistas del siglo XX.", "f": ""}, {"k": "flojo", "t": "Pero los obreros cobran un sueldo.", "r": "Cobran lo justo para seguir trabajando. El salario no responde a si ese trabajo los realiza como personas.", "why": "El salario no responde a la tesis: Marx habla de lo que el trabajo hace a la persona, no solo de lo que paga.", "f": ""}, {"k": "falacia", "t": "Mi tío tiene una fábrica y trata muy bien a sus empleados, así que en las fábricas no hay alienación.", "r": "Me alegro por los empleados de tu tío. Pero un caso no es el sistema, y la alienación no depende de que el jefe sea amable.", "why": "Sacas una conclusión general de un solo caso.", "f": "Generalización apresurada"}]}, {"say": "La historia de toda sociedad hasta hoy es la historia de la lucha de clases: libres y esclavos, señores y siervos, burgueses y proletarios. Y esa lucha llevará a una sociedad sin clases.", "opts": [{"k": "bueno", "t": "Tu teoría predecía que la revolución llegaría primero a los países más industrializados, como Inglaterra. Si cada vez que una predicción falla se reinterpreta la teoría para salvarla, ¿qué hecho podría refutarla?", "r": "En mis últimos años ya pensé que Rusia podría seguir otro camino. Pero acepto el desafío: Popper dirá que mis seguidores hicieron de mi teoría algo irrefutable. Una ciencia de la historia tiene que poder equivocarse.", "why": "Es la crítica de Karl Popper: una teoría que se adapta a cualquier resultado deja de ser científica.", "f": ""}, {"k": "flojo", "t": "Yo no veo ninguna lucha: en mi barrio todos nos llevamos bien.", "r": "La lucha de clases no es una pelea en la calle: es un choque de intereses entre quienes poseen los medios de producción y quienes solo tienen su trabajo.", "why": "Confundes un conflicto de intereses económicos con peleas visibles entre vecinos.", "f": ""}, {"k": "falacia", "t": "Tienes razón: o estás con los obreros o estás con los explotadores, no hay más.", "r": "Yo mismo describo clases intermedias: pequeños comerciantes, artesanos, campesinos. La realidad es más compleja que dos bandos, aunque creo que tiende a simplificarse.", "why": "Reduces todas las posiciones posibles a dos.", "f": "Falso dilema"}]}, {"say": "Los filósofos no han hecho más que interpretar el mundo de diversos modos; de lo que se trata es de transformarlo.", "opts": [{"k": "bueno", "t": "Para transformar bien el mundo primero hay que entenderlo bien: tú mismo pasaste años en la biblioteca del Museo Británico escribiendo El capital. Transformar sin entender puede salir muy mal.", "r": "Tienes razón: estudié años el capital antes de pedir su fin. No desprecio la teoría, sino la que se queda en contemplar. Teoría y práctica se necesitan.", "why": "Muestras que interpretar y transformar no se oponen: el propio Marx dedicó su vida al estudio.", "f": ""}, {"k": "flojo", "t": "Yo soy demasiado joven para cambiar el mundo.", "r": "Yo tenía veintinueve años cuando escribí el Manifiesto con Engels. Nadie es demasiado joven para entender cómo funciona su mundo.", "why": "Hablas de tu edad, no de la tesis sobre interpretar y transformar.", "f": ""}, {"k": "falacia", "t": "Nadie ha demostrado que pueda existir una sociedad sin clases, así que es imposible.", "r": "Que algo no se haya demostrado aún no prueba que sea imposible. Hace siglos nadie había visto una sociedad sin señores feudales, y llegó.", "why": "Que algo no se haya probado no demuestra que sea falso.", "f": "Apelación a la ignorancia"}]}], "fin": {"alto": "Has analizado con datos y razones, y sin miedo a criticar al maestro. Bien: de algunos de mis seguidores llegué a decir que, si eso era marxismo, yo no era marxista.", "medio": "Empiezas a ver lo que hay detrás de las ideas, pero aún te falta mirar las condiciones materiales. Duda de todo: era mi lema favorito.", "bajo": "Te quedaste en la superficie, con prejuicios y frases hechas. Las ideas dominantes de cada época son las de la clase dominante: aprende a sospechar de ellas."}},
  {"id": "mill", "q": "¿Debe la ley prohibir lo que solo te daña a ti?", "rounds": [{"say": "El único motivo para usar el poder contra la voluntad de alguien es evitar que dañe a otros. Su propio bien, físico o moral, no es razón suficiente. Sobre sí mismo, sobre su cuerpo y su mente, cada individuo es soberano.", "opts": [{"k": "bueno", "t": "Casi nada de lo que hago me afecta solo a mí. Si me arruino jugando, sufre mi familia. ¿Dónde está exactamente la frontera entre lo que solo me toca a mí y lo que daña a otros?", "r": "Es la objeción más repetida contra mí. Respondo que, si por beber dejas de pagar tus deudas o de cuidar a tus hijos, se te castigará por eso, no por beber. Pero admito que trazar la línea en cada caso no es fácil.", "why": "Planteas la objeción clásica al principio del daño: casi todos nuestros actos tienen efectos sobre los demás.", "f": ""}, {"k": "flojo", "t": "Pero hay gente que hace cosas muy raras con su vida.", "r": "Raro no es lo mismo que dañino. Al contrario: necesitamos gente excéntrica. Que tan pocos se atrevan a serlo es uno de los peligros de nuestra época.", "why": "Confundes lo extraño con lo perjudicial: no explicas qué daño causa.", "f": ""}, {"k": "falacia", "t": "Si dejamos que cada uno haga lo que quiera consigo mismo, pronto nadie respetará ninguna ley y viviremos en el caos.", "r": "No dije que cada uno haga lo que quiera: dije que no puede dañar a otros. De mi principio al caos hay muchos pasos que te saltas sin justificar.", "why": "Supones una cadena de consecuencias extremas que no se sigue de la idea.", "f": "Pendiente resbaladiza"}]}, {"say": "Hacer callar una opinión es un robo a toda la humanidad. Si la opinión es verdadera, perdemos la verdad; si es falsa, perdemos la imagen más clara de la verdad que nace de su choque con el error.", "opts": [{"k": "bueno", "t": "Hay palabras que dañan directamente: gritarle a una multitud furiosa, delante de la casa de alguien, que esa persona les roba el pan puede provocar una agresión. Ahí la libertad de expresión debe tener límites.", "r": "Uso casi ese mismo ejemplo: decir en un periódico que los comerciantes de grano matan de hambre a los pobres debe permitirse, pero no gritarlo ante la casa de uno de ellos a una multitud excitada. Cuando la palabra incita al daño, entra en mi principio. Has precisado bien.", "why": "Distingues entre expresar una opinión e incitar a dañar a alguien, como hace el propio Mill.", "f": ""}, {"k": "flojo", "t": "Hay opiniones muy aburridas que no aportan nada.", "r": "Puede ser. Pero ¿quién decide cuáles son aburridas? Y aun la opinión más pobre obliga a quien piensa lo contrario a recordar por qué lo piensa.", "why": "Que una opinión no te interese no es una razón para silenciarla ni para defenderla.", "f": ""}, {"k": "falacia", "t": "La mayoría de la gente piensa que las opiniones ofensivas deberían prohibirse, así que hay que prohibirlas.", "r": "Si toda la humanidad menos una persona pensara lo mismo, no tendría más derecho a silenciarla que ella a silenciar a la humanidad. Lo que temo es justamente la tiranía de la mayoría.", "why": "Que muchos lo piensen no lo hace verdadero ni justo.", "f": "Apelación a la mayoría"}]}, {"say": "Unos placeres valen más que otros. Es mejor ser un ser humano insatisfecho que un cerdo satisfecho; mejor ser Sócrates insatisfecho que un necio satisfecho.", "opts": [{"k": "bueno", "t": "¿Quién decide qué placer es superior? Dices que quienes conocen los dos. Pero mucha gente que conoce la lectura y el sofá acaba eligiendo el sofá. Tus jueces no siempre te dan la razón.", "r": "Lo sé, y lo digo yo mismo: muchos pierden la capacidad para los placeres más nobles, que es como una planta delicada que muere si no se cuida. Pero reconozco que el veredicto de los jueces competentes no es tan claro como me gustaría.", "why": "Señalas una dificultad real del criterio de Mill para distinguir placeres superiores e inferiores.", "f": ""}, {"k": "flojo", "t": "A mí me gustan más los videojuegos que la poesía.", "r": "Es posible. Pero tu gusto de hoy no decide cuál vale más. ¿Has probado los dos con la misma atención?", "why": "Das una preferencia personal en lugar de una razón.", "f": ""}, {"k": "falacia", "t": "Eso lo dices porque eres un intelectual que se cree superior a la gente normal.", "r": "Puede que yo sea un intelectual, pero eso no hace falso lo que digo. Discute mi argumento, no mi biblioteca.", "why": "Atacas a quien habla en lugar de a su razonamiento.", "f": "Ataque a la persona"}]}, {"say": "Una acción es correcta en la medida en que tiende a producir felicidad, no solo la de quien actúa, sino la de todos los afectados. Ese es el principio de utilidad.", "opts": [{"k": "bueno", "t": "Entonces sería correcto condenar a un inocente si así se calmara a una multitud y se evitaran disturbios. Hay derechos que no se pueden sacrificar aunque la suma de felicidad aumente.", "r": "Es la objeción más seria contra el utilitarismo. Respondo que la justicia protege la seguridad, el más vital de nuestros intereses: nadie viviría tranquilo en un país que condena inocentes. Pero me obligas a mostrar que los derechos no son una excepción a la utilidad.", "why": "Presentas el contraejemplo clásico de la justicia contra el utilitarismo.", "f": ""}, {"k": "flojo", "t": "Yo solo quiero ser feliz yo; los demás que se ocupen de lo suyo.", "r": "Eso no es una objeción a mi principio, es una confesión de egoísmo. Y además, quien solo piensa en sí mismo suele ser bastante infeliz.", "why": "Expresas una actitud, pero no das ninguna razón contra el principio.", "f": ""}, {"k": "falacia", "t": "Siempre hemos juzgado las acciones por las reglas de nuestros mayores, no por sus consecuencias, y así debe seguir siendo.", "r": "El despotismo de la costumbre es el mayor obstáculo al progreso humano. Que una regla sea antigua no dice si hace bien o mal a alguien.", "why": "Que algo se haya hecho siempre no lo hace correcto.", "f": "Apelación a la tradición"}]}], "fin": {"alto": "Has discutido con libertad y con razones, que es lo que yo pido a cualquier ciudadano. Harriet, con quien pensé buena parte de mis libros, estaría de acuerdo: así avanza la verdad.", "medio": "Algunas de tus objeciones fueron buenas; otras se apoyaron en gustos o costumbres. Escucha también a quien piensa lo contrario: así se afila la verdad.", "bajo": "Te apoyaste en la mayoría y en la costumbre. Cuidado: una sociedad donde todos piensan igual deja de pensar."}},
  {"id": "beauvoir", "q": "¿Se nace mujer o se llega a serlo?", "rounds": [{"say": "No se nace mujer: se llega a serlo. Ningún destino biológico, psíquico o económico define la figura que la mujer tiene en la sociedad; es el conjunto de la civilización el que la elabora.", "opts": [{"k": "bueno", "t": "Pero el cuerpo existe: hay diferencias biológicas reales entre hombres y mujeres. ¿No estás negando algo evidente?", "r": "No las niego: dediqué los primeros capítulos de mi libro a la biología. Pero el cuerpo no es una cosa, es una situación: es nuestra forma de estar en el mundo. Los hechos biológicos importan, aunque no deciden por sí solos el sentido de una vida.", "why": "Planteas la objeción del peso de la biología, que Beauvoir toma en serio y matiza.", "f": ""}, {"k": "flojo", "t": "Yo conozco chicas a las que les gustan las cosas que se consideran de chicas.", "r": "Claro que existen. La pregunta es de dónde vienen esos gustos. Desde muy pequeñas se nos dan muñecas y se nos dice que seamos dulces. Lo que parece natural muchas veces se ha aprendido.", "why": "Das un ejemplo, pero no muestras que esos gustos sean innatos y no aprendidos.", "f": ""}, {"k": "falacia", "t": "Siempre ha sido así: los hombres en la vida pública y las mujeres en casa. Por algo será.", "r": "Que algo haya sido siempre así es justo lo que hay que explicar. Además, esa historia la han contado casi siempre los hombres.", "why": "Que una situación sea antigua no demuestra que sea natural ni justa.", "f": "Apelación a la tradición"}]}, {"say": "La humanidad es masculina, y el hombre define a la mujer no en sí misma, sino en relación con él. Él es el Sujeto, el Absoluto; ella es la Otra.", "opts": [{"k": "bueno", "t": "Si la mujer es la Otra, ¿por qué tantas mujeres lo aceptaron durante siglos? Si todo fuera imposición, habrían resistido más.", "r": "Es una pregunta que yo misma me hago. Las mujeres no tenían medios concretos ni una historia común que las uniera, y además existe la tentación de huir de la libertad: es cómodo que otro decida por ti. Por eso hablo de complicidad, y eso convierte el problema en una cuestión moral.", "why": "Planteas la complicidad de los oprimidos, una cuestión que Beauvoir analiza en su obra.", "f": ""}, {"k": "flojo", "t": "Hoy eso ya no pasa, las cosas han cambiado mucho.", "r": "Escribí esto en 1949, y algo ha cambiado, sí, gracias a quienes lucharon. Pero mira bien: ¿en los libros, las películas y los trabajos se piensa siempre al hombre como lo normal?", "why": "Afirmas un cambio sin examinar si la situación ha desaparecido de verdad.", "f": ""}, {"k": "falacia", "t": "Eso lo dices porque eres mujer, así que no eres imparcial.", "r": "Los hombres han escrito sobre las mujeres durante siglos siendo juez y parte, y nadie les dijo eso. Juzga mis argumentos, no mi sexo.", "why": "Rechazas la idea por quién la dice, no por sus razones.", "f": "Ataque a la persona"}]}, {"say": "Querer ser libre es también querer libres a los demás. Mi libertad no puede realizarse si los otros están oprimidos.", "opts": [{"k": "bueno", "t": "¿Y si mi libertad choca con la de otra persona? Si quiero algo que limita a alguien, no tengo ninguna regla para saber cuál debe ganar.", "r": "No hay recetas: por eso hablo de una moral de la ambigüedad. Hay que decidir en cada situación concreta. Pero sí te digo una cosa: la «libertad» de oprimir no merece respeto, porque niega la libertad de los demás.", "why": "Señalas que el principio no resuelve automáticamente los conflictos entre libertades.", "f": ""}, {"k": "flojo", "t": "La libertad es hacer lo que uno quiere.", "r": "Eso es el capricho. La libertad se proyecta hacia el futuro, hacia lo que construimos. Hacer lo que apetece en cada momento no nos hace libres.", "why": "Confundes la libertad con el capricho.", "f": ""}, {"k": "falacia", "t": "O hay alguien que manda y otros que obedecen, o hay caos. Tú eliges.", "r": "¿Por qué solo esas dos? También existe la cooperación entre iguales, como en una amistad verdadera.", "why": "Presentas solo dos opciones cuando hay otras.", "f": "Falso dilema"}]}, {"say": "La libertad no es solo una idea: necesita condiciones concretas. Por el trabajo la mujer ha recorrido gran parte de la distancia que la separaba del hombre. Sin independencia económica, la mujer libre solo existe en el papel.", "opts": [{"k": "bueno", "t": "El trabajo puede liberar, pero también puede ser otra carga: muchas mujeres trabajan fuera y luego hacen todo el trabajo de casa. Un empleo no basta si nada más cambia.", "r": "Tienes toda la razón, y lo escribí: la mujer que trabaja suele soportar una doble carga y un trabajo que también la explota. El trabajo no libera por sí solo; hace falta que cambie la sociedad entera.", "why": "Muestras que la independencia económica es necesaria pero no suficiente, como reconoce Beauvoir.", "f": ""}, {"k": "flojo", "t": "Bueno, cada una que haga lo que quiera.", "r": "Sí, pero una elección sin alternativas reales no es una elección libre. Para elegir, hay que tener opciones.", "why": "Respondes con una frase general que no toca el problema de las condiciones.", "f": ""}, {"k": "falacia", "t": "Todas las mujeres que conozco que trabajan son felices, así que el problema está resuelto.", "r": "Conoces a unas pocas personas. ¿Y las que no conoces? Unos casos no hacen una regla.", "why": "Sacas una conclusión general a partir de muy pocos casos.", "f": "Generalización apresurada"}]}], "fin": {"alto": "Has pensado tu situación sin aceptarla como un destino. La libertad no es lo que te dieron al nacer, sino lo que haces con tu situación.", "medio": "Empiezas a ver que muchas cosas «naturales» se aprenden. Sigue mirando: lo que parece evidente es lo primero que hay que examinar.", "bajo": "Te refugiaste en la costumbre y en lo que siempre se ha dicho. Pero nadie nace con un destino escrito."}},
  {"id": "camus", "q": "¿Tiene sentido la vida si el mundo no lo tiene?", "rounds": [{"say": "Solo hay una pregunta filosófica verdaderamente seria: juzgar si la vida vale o no la pena de ser vivida. Todo lo demás viene después.", "opts": [{"k": "bueno", "t": "Hay otra pregunta igual de seria: qué podemos hacernos unos a otros. Tú luchaste en la Resistencia. ¿No es tan urgente saber si es legítimo matar o dejar morir a otros?", "r": "Tienes razón, y por eso escribí El hombre rebelde: pasé de la pregunta por la propia vida a la pregunta por la vida de los demás. Me rebelo, luego somos: la rebeldía me descubre que no estoy solo.", "why": "Amplías la pregunta de lo individual a lo colectivo, como hizo el propio Camus en su obra posterior.", "f": ""}, {"k": "flojo", "t": "La vida vale la pena porque hay cosas divertidas.", "r": "No lo desprecio: yo amo el sol y el mar de Argel. Pero eso es un sentimiento, no todavía una respuesta. ¿Qué haces el día en que el decorado se derrumba y aparece el «para qué»?", "why": "Das una razón agradable pero superficial, que no responde a la pregunta de fondo.", "f": ""}, {"k": "falacia", "t": "La mayoría de la gente nunca se hace esa pregunta y vive tranquila, así que la pregunta sobra.", "r": "El sentimiento de lo absurdo puede golpear a cualquiera en la esquina de cualquier calle. Que muchos no se lo pregunten hoy no significa que la pregunta no exista.", "why": "Que la mayoría no se plantee algo no demuestra que no tenga importancia.", "f": "Apelación a la mayoría"}]}, {"say": "Lo absurdo nace del choque entre la llamada humana, que pide sentido, y el silencio irrazonable del mundo.", "opts": [{"k": "bueno", "t": "Dices que el mundo calla. Pero no puedes demostrar que no tenga sentido; solo que tú no lo encuentras. ¿No conviertes un «no sé» en un «no hay»?", "r": "Precisamente por eso lo digo así: no sé si este mundo tiene un sentido que lo supera. Sé que yo no conozco ese sentido y que ahora me es imposible conocerlo. No afirmo que no exista; me niego a fingir que lo conozco.", "why": "Distingues entre no conocer un sentido y afirmar que no existe; Camus mismo hace esa distinción.", "f": ""}, {"k": "flojo", "t": "A mí el mundo no me parece absurdo, me parece normal.", "r": "A casi todos nos lo parece, hasta que un día se rompe la rutina: levantarse, trabajar, comer, dormir. Entonces surge el «¿por qué?», y ahí empieza todo.", "why": "No respondes al argumento: solo describes tu impresión.", "f": ""}, {"k": "falacia", "t": "O sea, que según tú nada importa y da igual cómo vivas.", "r": "Nunca he dicho eso. Digo lo contrario: lo absurdo exige vivir con lucidez y con rebeldía. Me atribuyes una idea que no es la mía para refutarla con más facilidad.", "why": "Deformas la tesis del otro para atacar una versión más débil.", "f": "Hombre de paja"}]}, {"say": "Ante lo absurdo hay quien huye de la vida y quien salta a una esperanza que lo explica todo. Yo prefiero una tercera vía: vivir con lucidez, sin apelar a nada más allá. Eso es la rebeldía.", "opts": [{"k": "bueno", "t": "Muchos creyentes encuentran en su fe fuerzas para ayudar a los demás. ¿No es injusto llamar a eso una huida?", "r": "Lo dije ante unos cristianos: no parto de que la verdad cristiana sea ilusoria, sino de que yo no he podido entrar en ella. Respeto a quien cree y lucha conmigo contra el sufrimiento. Mi crítica va contra la esperanza que sirve para no mirar.", "why": "Señalas que la fe no siempre es evasión; Camus reconoció ese respeto en su diálogo con los cristianos.", "f": ""}, {"k": "flojo", "t": "Yo prefiero no pensar en eso.", "r": "Es lo más cómodo, lo sé. Pero no pensar en ello no lo hace desaparecer. Yo prefiero mirar las cosas de frente.", "why": "Evitas la pregunta en vez de responderla.", "f": ""}, {"k": "falacia", "t": "O crees en algo que da sentido a todo, o te hundes en la desesperación. No hay más.", "r": "Es justo lo que niego. Entre la esperanza que lo explica todo y la desesperación está la rebeldía: vivir, crear y luchar sabiendo que no hay garantías.", "why": "Presentas solo dos opciones cuando hay una tercera.", "f": "Falso dilema"}]}, {"say": "Sísifo empuja su roca montaña arriba, y la roca vuelve a caer, una y otra vez. Pero la lucha hacia las cumbres basta para llenar un corazón humano. Hay que imaginarse a Sísifo feliz.", "opts": [{"k": "bueno", "t": "Sísifo no eligió su castigo: se lo impusieron los dioses. Llamar «felicidad» a aceptar lo que no puedes cambiar ¿no podría servir para que los oprimidos se resignen?", "r": "El peligro existe si se lee mal. Sísifo no se resigna: está por encima de su destino porque lo mira con lucidez y desprecio. Y cuando la injusticia la causan los hombres, la respuesta no es aceptarla, sino rebelarse. Me obligas a dejarlo claro.", "why": "Señalas el riesgo de leer el mito como resignación, y obligas a distinguir lucidez de conformismo.", "f": ""}, {"k": "flojo", "t": "Sísifo no puede ser feliz: empujar una piedra es aburridísimo.", "r": "La roca es su asunto, y él lo sabe. Su felicidad no está en la piedra, sino en mirar su destino sin mentirse.", "why": "No discutes la idea: te quedas en la imagen del castigo.", "f": ""}, {"k": "falacia", "t": "Todos los existencialistas sois unos pesimistas, así que tu Sísifo feliz es un truco.", "r": "Para empezar, no soy existencialista: lo he dicho muchas veces. Y no soy pesimista. Juzgas mi idea por una etiqueta y un tópico, no por lo que digo.", "why": "Aplicas un tópico general sin comprobarlo en este caso concreto.", "f": "Generalización apresurada"}]}], "fin": {"alto": "Has mirado lo absurdo de frente sin huir ni rendirte. Eso es rebelarse. En medio del invierno, has encontrado en ti un verano invencible.", "medio": "A veces miraste de frente y a veces buscaste un refugio. La lucidez cuesta, pero es lo que hace libre.", "bajo": "Te escondiste en lo que dicen todos y en etiquetas fáciles. Lo absurdo no desaparece por no mirarlo."}},
  {"id": "arendt", "q": "¿Puede una persona corriente hacer un gran mal?", "rounds": [{"say": "En Jerusalén vi juzgar a Eichmann, uno de los organizadores de las deportaciones de judíos. Esperaba un monstruo y encontré a un hombre corriente, que hablaba con frases hechas. Lo terrible no era su odio, sino su incapacidad de pensar. Lo llamé la banalidad del mal.", "opts": [{"k": "bueno", "t": "¿Y si Eichmann representó un papel? Ante el tribunal le convenía parecer un funcionario gris. Quizás era un antisemita convencido que fingía.", "r": "Es posible que actuara, y muchos, como Scholem, me criticaron con dureza. Pero mi tesis no depende solo de él: un mal tan grande necesitó a miles de personas normales que no se detuvieron a pensar. Y banal no quiere decir que sus actos fueran poca cosa.", "why": "Planteas una objeción histórica seria: el acusado pudo fingir su mediocridad para defenderse.", "f": ""}, {"k": "flojo", "t": "Si hizo eso, tenía que estar loco.", "r": "Media docena de psiquiatras lo examinaron y lo declararon normal. Eso es lo inquietante: no hacía falta estar loco.", "why": "Ofreces una explicación cómoda que los hechos del juicio no confirman.", "f": ""}, {"k": "falacia", "t": "Si dices que no era un monstruo, estás defendiendo a los nazis.", "r": "Yo aprobé que fuera condenado a muerte. Comprender no es justificar. Me atribuyes lo contrario de lo que digo.", "why": "Deformas la tesis para atacar algo que el otro no ha dicho.", "f": "Hombre de paja"}]}, {"say": "Eichmann decía que solo obedecía órdenes. Pero en política obedecer y apoyar son lo mismo: un adulto que obedece está dando su apoyo.", "opts": [{"k": "bueno", "t": "Quien desobedecía podía perder la vida o poner en peligro a su familia. ¿Podemos exigir a todo el mundo que sea un héroe?", "r": "No pido héroes. Pido no participar. Bajo el terror, la mayoría cede, pero algunos no lo hacen: en Dinamarca casi todo un pueblo protegió a sus judíos. No hace falta más para que el mundo siga siendo habitable. Aun así, reconozco que el miedo pesa mucho.", "why": "Planteas el peso real del miedo, y obligas a distinguir entre exigir heroísmo y exigir no colaborar.", "f": ""}, {"k": "flojo", "t": "Si tu jefe te manda algo, tienes que hacerlo: es tu trabajo.", "r": "Esa es la excusa del engranaje. Pero ante un tribunal no se juzga a una pieza de una máquina, sino a una persona que eligió.", "why": "Repites la misma excusa que se discute, sin dar razones nuevas.", "f": ""}, {"k": "falacia", "t": "Todos los funcionarios alemanes obedecían, así que no se le puede culpar a él.", "r": "Un tribunal no juzga a una mayoría, sino a una persona. Que muchos hicieran lo mismo no vuelve inocente a ninguno.", "why": "Que muchos hagan algo no lo hace correcto ni quita responsabilidad.", "f": "Apelación a la mayoría"}]}, {"say": "Pensar es un diálogo silencioso conmigo mismo, como enseñaba Sócrates. Quien piensa tiene que vivir consigo mismo, y por eso hay cosas que no hará: no quiere convivir con un asesino.", "opts": [{"k": "bueno", "t": "Pero hubo profesores y filósofos muy inteligentes que apoyaron a los nazis. Pensar mucho no garantiza actuar bien.", "r": "Lo sé mejor que nadie: en 1933 vi a muchos intelectuales, incluso amigos, sumarse al régimen. Pero no hablo de inteligencia ni de saber muchas cosas, sino de detenerse a examinar lo que uno hace. Tienes razón en que pensar no es una vacuna segura.", "why": "Das un contraejemplo histórico que obliga a distinguir pensar de ser inteligente.", "f": ""}, {"k": "flojo", "t": "Yo pienso todo el rato, así que no haría nada malo.", "r": "Tener pensamientos no es lo mismo que pensar. Pensar es pararse y preguntarse: ¿qué estoy haciendo?", "why": "Confundes tener ideas en la cabeza con examinar lo que haces.", "f": ""}, {"k": "falacia", "t": "Nadie ha demostrado que pensar nos haga mejores, así que no sirve para nada.", "r": "Que no se pueda demostrar no prueba lo contrario. Y no digo que pensar nos haga santos: digo que no pensar hace el mal mucho más fácil.", "why": "Que algo no esté demostrado no prueba que sea falso.", "f": "Apelación a la ignorancia"}]}, {"say": "Cada ser humano que nace trae al mundo algo nuevo: la capacidad de empezar. La política no es mandar y obedecer, sino actuar juntos. El poder nace cuando las personas actúan de común acuerdo.", "opts": [{"k": "bueno", "t": "Actuar juntos es poderoso, pero una multitud también puede empezar algo terrible. La acción necesita límites: leyes, derechos, promesas.", "r": "Estoy de acuerdo. La acción es imprevisible y no se puede deshacer. Por eso necesitamos la promesa, que da algo de estabilidad al futuro, y el perdón, que nos libera del pasado. Y necesitamos leyes que protejan a cada uno.", "why": "Señalas el riesgo de la acción colectiva, y Arendt responde con la promesa, el perdón y la ley.", "f": ""}, {"k": "flojo", "t": "Una sola persona no puede cambiar nada.", "r": "Sola, quizás no. Pero el poder no lo tiene nadie solo: surge cuando las personas se reúnen y actúan juntas. Y todo empieza cuando alguien se atreve a dar el primer paso.", "why": "Afirmas algo pesimista sin considerar la acción conjunta.", "f": ""}, {"k": "falacia", "t": "Es mejor dejar la política a los que saben: para eso son líderes y expertos.", "r": "Lo he dicho muchas veces: nadie tiene derecho a obedecer. Si dejas el mundo común solo en manos de otros, renuncias a lo que te hace ciudadano.", "why": "Que alguien tenga autoridad no basta para que debamos dejar de juzgar.", "f": "Apelación a la autoridad"}]}], "fin": {"alto": "Has pensado en lugar de repetir. Esa es la mejor defensa contra el mal: detenerse, juzgar por uno mismo y actuar con los demás.", "medio": "A veces pensaste y a veces repetiste. Recuerda: el mal crece cuando dejamos de preguntarnos qué estamos haciendo.", "bajo": "Te refugiaste en la mayoría y en la obediencia. Así es como empiezan los tiempos oscuros. Atrévete a pensar."}},
  {"id": "confucio", "q": "¿Nos hace buenos seguir las normas?", "rounds": [{"say": "Dominarse a uno mismo y volver a los ritos: eso es la humanidad. Los ritos, las formas de respeto que heredamos, nos enseñan a tratar bien a los demás.", "opts": [{"k": "bueno", "t": "Pero se pueden cumplir todos los ritos y ser falso por dentro: hacer reverencias sin sentir respeto. La forma sin el corazón está vacía.", "r": "Eso mismo enseño yo: si un hombre no es humano, ¿de qué le sirven los ritos? ¿Acaso los ritos son solo jade y seda? Has entendido que la forma y el corazón deben ir juntos.", "why": "Señalas que la norma externa no basta sin la actitud interior, una idea central de las Analectas.", "f": ""}, {"k": "flojo", "t": "Los ritos son cosas antiguas y aburridas.", "r": "Me preguntaron una vez por la raíz de los ritos. Respondí: en las celebraciones, mejor la sencillez que el lujo; en el luto, mejor el dolor sincero que la ceremonia. Pregúntate qué expresan antes de llamarlos aburridos.", "why": "Juzgas por la apariencia sin examinar el sentido de las normas.", "f": ""}, {"k": "falacia", "t": "Si empezamos a saltarnos un rito, acabaremos sin respeto por nada y la sociedad se derrumbará.", "r": "Yo mismo acepté cambios: antes el gorro ceremonial se hacía de cáñamo; hoy se hace de seda, que es más económico, y sigo la costumbre nueva. Cambiar una forma no destruye el respeto.", "why": "Supones una cadena de consecuencias catastróficas sin justificarla.", "f": "Pendiente resbaladiza"}]}, {"say": "Hoy se llama piedad filial a poder alimentar a los padres. Pero también alimentamos a los perros y a los caballos. Sin respeto, ¿dónde está la diferencia?", "opts": [{"k": "bueno", "t": "¿Y si un padre actúa mal? Respetarlo no puede significar obedecerlo en todo.", "r": "Tienes razón en parte. Al servir a los padres, se les puede advertir con suavidad cuando se equivocan. Si no escuchan, sigo respetándolos y no me rebelo. Pero respetar no es callar siempre.", "why": "Planteas el límite de la obediencia, que el propio Confucio matiza con la advertencia respetuosa.", "f": ""}, {"k": "flojo", "t": "Hoy los jóvenes saben más que los padres, por la tecnología.", "r": "Yo dije que hay que respetar a los jóvenes: ¿quién sabe si no superarán a los de ahora? Pero saber usar herramientas no es lo mismo que saber vivir.", "why": "Confundes saber más cosas con merecer menos respeto.", "f": ""}, {"k": "falacia", "t": "Todos mis amigos piensan que los padres son unos pesados, así que es verdad.", "r": "Cuando todos odian a alguien, hay que examinarlo; cuando todos lo aman, también hay que examinarlo. La opinión de muchos no ahorra el juicio propio.", "why": "Que muchos piensen algo no lo hace verdadero.", "f": "Apelación a la mayoría"}]}, {"say": "Si guías al pueblo con leyes y castigos, evitará el castigo pero no sentirá vergüenza. Si lo guías con la virtud y los ritos, sentirá vergüenza y además se corregirá.", "opts": [{"k": "bueno", "t": "Eso funciona si el gobernante es virtuoso. Pero ¿y si no lo es? Las leyes claras protegen al pueblo incluso cuando gobierna alguien mediocre.", "r": "Es una objeción seria, y los legistas la repetirán. Por eso insisto en educar a quienes gobiernan. No digo que las leyes sobren: yo también sé juzgar pleitos como cualquiera. Lo que busco es que no haga falta pleitear.", "why": "Planteas la objeción clásica de los legistas chinos: no podemos depender de la virtud de quien manda.", "f": ""}, {"k": "flojo", "t": "Los castigos funcionan porque la gente tiene miedo.", "r": "Funcionan para evitar el castigo, sí. Pero la gente aprende a esquivar la ley, no a ser buena. Eso es justo lo que digo.", "why": "Repites lo que Confucio ya admite, sin responder a su argumento.", "f": ""}, {"k": "falacia", "t": "Los reinos que conocieron tus consejos acabaron conquistados, así que la virtud debilita a los Estados.", "r": "Ningún señor de mi tiempo me hizo caso de verdad: recorrí muchos reinos buscando uno. Y aunque así fuera, que algo ocurra después no prueba que sea su causa.", "why": "Supones que porque algo ocurrió después, fue causado por lo anterior.", "f": "Falsa causa"}]}, {"say": "Un discípulo me pidió una sola palabra para guiar toda la vida. Le respondí: reciprocidad. Lo que no quieras para ti, no lo hagas a los demás.", "opts": [{"k": "bueno", "t": "Esa regla es buena, pero los gustos cambian: lo que yo no quiero, otro puede quererlo. Hace falta ponerse de verdad en el lugar del otro, no solo en el mío.", "r": "Por eso también enseño la otra cara: quien es humano, deseando establecerse a sí mismo, ayuda a establecerse a los demás. Hay que partir de uno mismo para comprender al otro, pero sin quedarse en uno mismo.", "why": "Señalas un límite de la regla de oro y obligas a completarla con la empatía activa.", "f": ""}, {"k": "flojo", "t": "Eso ya lo sabe todo el mundo.", "r": "Saberlo no es lo mismo que amarlo, y amarlo no es lo mismo que disfrutar practicándolo. ¿Lo practicas?", "why": "Confundes conocer una regla con vivirla.", "f": ""}, {"k": "falacia", "t": "¡Qué regla tan bonita! Me emociona tanto que tiene que ser verdad.", "r": "Me alegra que te conmueva. Pero aprender sin pensar es inútil, y pensar sin aprender es peligroso. El sentimiento no sustituye a la reflexión.", "why": "Tomas la emoción que produce una idea como prueba de que es verdadera.", "f": "Apelación a la emoción"}]}], "fin": {"alto": "Has unido el respeto a las formas con un corazón sincero. Así se forma el ser humano noble: estudiando y practicando sin descanso.", "medio": "Has aprendido algo, pero todavía te falta pensar lo que aprendes. Quien repasa lo antiguo y descubre lo nuevo puede ser maestro.", "bajo": "Seguiste a los demás o a tus emociones sin examinarlas. El noble busca en sí mismo; el mezquino busca en los otros."}},
  {"id": "buda", "q": "¿Se puede dejar de sufrir?", "rounds": [{"say": "Esta es la noble verdad del sufrimiento: nacer, envejecer, enfermar y morir es sufrimiento. Estar unido a lo que no amamos y separado de lo que amamos es sufrimiento. No obtener lo que deseamos es sufrimiento.", "opts": [{"k": "bueno", "t": "Pero la vida también tiene alegrías reales: la amistad, la música, una tarde con la familia. Llamarlo todo sufrimiento parece exagerado.", "r": "No niego las alegrías: en los placeres hay gratificación, pero también peligro, porque son impermanentes. Y sobre la amistad, le dije a Ananda que la buena amistad no es la mitad de la vida santa: es toda. Quizás «insatisfacción» exprese mejor lo que quiero decir.", "why": "Matizas la primera noble verdad y obligas a precisar el sentido de dukkha, que no significa solo dolor.", "f": ""}, {"k": "flojo", "t": "Yo ahora mismo estoy bien, no sufro.", "r": "Me alegro. Pero mira ese bienestar: ¿durará siempre? Todo lo que surge está destinado a cesar.", "why": "Hablas de tu momento presente, pero la tesis trata de lo que es impermanente.", "f": ""}, {"k": "falacia", "t": "Tú eras un príncipe rico: ¿qué vas a saber tú del sufrimiento?", "r": "Fui criado con delicadeza y tuve palacios para cada estación. Pero allí mismo comprendí que yo también envejecería, enfermaría y moriría. Además, juzga mi enseñanza, no mi cuna.", "why": "Rechazas la idea por el origen de quien habla, no por sus razones.", "f": "Ataque a la persona"}]}, {"say": "El origen del sufrimiento es el ansia: la sed que nos lleva de un deseo a otro. Sed de placeres, sed de existir, sed de no existir.", "opts": [{"k": "bueno", "t": "Pero no todo deseo es malo: querer que otros dejen de sufrir, o desear despertar, también es desear. Si eliminamos todo deseo, ¿no eliminamos también eso?", "r": "Mi discípulo Ananda lo explicó bien: quien camina hacia un parque desea llegar, y cuando llega, ese deseo se apaga. El deseo que lleva a liberarse se usa como una balsa para cruzar el río, y luego se deja. Lo que hay que apagar es la sed que encadena.", "why": "Planteas la clásica «paradoja del deseo»: también desear liberarse del deseo es un deseo.", "f": ""}, {"k": "flojo", "t": "Sin deseos, la vida sería muy aburrida.", "r": "¿Estás seguro? Observa la sed que nunca se sacia: ¿te hace la vida más interesante o más cansada?", "why": "Das una impresión, pero no un argumento contra la tesis.", "f": ""}, {"k": "falacia", "t": "Todo el mundo vive persiguiendo lo que desea. Si tantos lo hacen, no puede ser el problema.", "r": "Este mundo está ciego: pocos ven con claridad. Que muchos sigan el mismo camino no prueba que lleve a la paz.", "why": "Que muchos hagan algo no demuestra que sea bueno.", "f": "Apelación a la mayoría"}]}, {"say": "Hay dos extremos que debe evitar quien busca la liberación: entregarse a los placeres de los sentidos y torturarse a uno mismo. Yo los probé los dos. Entre ambos está el camino medio.", "opts": [{"k": "bueno", "t": "El camino medio suena sensato, pero ¿dónde está el medio? Lo que para uno es moderación, para otro es exceso.", "r": "Se lo expliqué a Sona, que sabía tocar el laúd: si las cuerdas del laúd están demasiado tensas o demasiado flojas, no suenan bien. Cada uno debe afinar su esfuerzo según su propia fuerza. El medio no se calcula: se encuentra practicando.", "why": "Señalas que «el término medio» no es una regla exacta y obligas a precisar cómo se encuentra.", "f": ""}, {"k": "flojo", "t": "Yo prefiero los extremos, son más emocionantes.", "r": "Yo también los preferí: viví entre lujos y después casi muero de hambre como asceta. Ninguno de los dos me llevó a la paz.", "why": "Expresas un gusto, pero no das una razón.", "f": ""}, {"k": "falacia", "t": "O disfrutas de todos los placeres o vives como un monje en una cueva. No hay otra opción.", "r": "Esos son justo los dos extremos que rechazo. Hay un camino entre ellos: el óctuple sendero.", "why": "Presentas solo dos opciones cuando hay más.", "f": "Falso dilema"}]}, {"say": "No creáis algo solo porque se repite, porque es tradición, porque está en los textos o porque lo dice vuestro maestro. Cuando sepáis por vosotros mismos que algo conduce al daño y al sufrimiento, abandonadlo.", "opts": [{"k": "bueno", "t": "Pero hay cosas de tu enseñanza que no puedo comprobar, como que renacemos. ¿No me pides creer en eso sin verlo?", "r": "Es una pregunta honrada. A los kalamas les dije: si hay otro mundo, quien vive bien estará tranquilo; si no lo hay, vivirá feliz en esta vida, libre de odio. El camino vale la pena aunque no puedas comprobarlo todo.", "why": "Señalas un límite real: no todo en la enseñanza puede comprobarse por uno mismo.", "f": ""}, {"k": "flojo", "t": "Entonces cada uno puede creer lo que quiera.", "r": "No. Te pido que examines: lo que conduce al odio y al daño, y lo critican los sabios, debe abandonarse. Eso no es creer cualquier cosa.", "why": "Sacas una conclusión que no se sigue de lo que se ha dicho.", "f": ""}, {"k": "falacia", "t": "Pero tú eres el Buda, el Despierto: si lo dices tú, tiene que ser verdad.", "r": "Acabo de decirte que no creas por la autoridad de un maestro. Sé una isla para ti mismo: compruébalo con tu propia experiencia.", "why": "Aceptar algo solo por quién lo dice es justo lo que el Buda desaconseja.", "f": "Apelación a la autoridad"}]}], "fin": {"alto": "Has examinado cada idea con atención y sin aferrarte a ella. Tú debes hacer el esfuerzo: quienes han despertado solo señalan el camino.", "medio": "Has visto parte del camino. Sigue observando tu mente con paciencia: la claridad llega poco a poco.", "bajo": "Te dejaste llevar por la costumbre y por la autoridad. Mira por ti mismo: nadie puede caminar por ti."}},
  {"id": "agustin", "q": "¿De dónde viene el mal?", "rounds": [{"say": "Durante años me pregunté: ¿de dónde viene el mal? Los maniqueos decían que hay dos principios, uno bueno y otro malo. Yo descubrí que el mal no es una sustancia, sino la falta de un bien que debería estar, como la enfermedad es falta de salud.", "opts": [{"k": "bueno", "t": "Si el mal es solo una falta, ¿por qué el dolor se siente tan real? Un dolor de muelas no parece una simple ausencia.", "r": "La ceguera también es una falta, y es muy real para el ciego. No digo que el mal no exista, sino que no es una cosa creada: es un bien dañado. Aun así, reconozco que esta explicación puede sonar fría a quien sufre.", "why": "Planteas la objeción clásica a la teoría del mal como privación: el sufrimiento parece algo positivo.", "f": ""}, {"k": "flojo", "t": "El mal viene de las personas malas.", "r": "¿Y de dónde viene su maldad? Has cambiado la pregunta de sitio, pero no la has respondido.", "why": "Das una respuesta que solo aplaza la pregunta.", "f": ""}, {"k": "falacia", "t": "Como nadie ha podido explicar el mal del todo, queda demostrado que Dios no existe.", "r": "Que no sepamos explicar algo del todo no prueba nada, ni a favor ni en contra. Yo mismo tardé años en entenderlo, y aún hay mucho que no comprendo.", "why": "Sacas una conclusión de la falta de explicación, como si no saber algo demostrara lo contrario.", "f": "Apelación a la ignorancia"}]}, {"say": "De joven robé unas peras con mis amigos. No tenía hambre: las tiramos a los cerdos. Me gustó hacer lo prohibido. Así comprendí que el mal nace de la voluntad libre cuando se aparta del bien mayor.", "opts": [{"k": "bueno", "t": "Si Dios sabía de antemano que robarías, ¿eras realmente libre? Parece que no podías hacer otra cosa.", "r": "Es la objeción que me planteó mi amigo Evodio. Respondo que saber no es causar: tu recuerdo de lo que hiciste ayer no te obligó a hacerlo. Dios sabe lo que harás libremente. Pero confieso que es uno de los misterios más difíciles.", "why": "Planteas el problema clásico de la presciencia divina y la libertad humana.", "f": ""}, {"k": "flojo", "t": "Robar unas peras no es tan grave.", "r": "Lo importante no son las peras, sino por qué lo hice: no las quería a ellas, amaba la falta misma. Eso es lo que me asustó.", "why": "Te quedas en la gravedad del acto y no en la pregunta por su origen.", "f": ""}, {"k": "falacia", "t": "Tú de joven fuiste un juerguista: ¿quién eres tú para hablar del mal?", "r": "Precisamente porque lo viví, puedo hablar de él: lo cuento en mis Confesiones. Mi pasado no hace falso mi argumento.", "why": "Atacas la vida de quien habla en lugar de su razonamiento.", "f": "Ataque a la persona"}]}, {"say": "Dos amores fundaron dos ciudades: el amor de sí mismo hasta el desprecio de Dios, la ciudad terrena; el amor de Dios hasta el desprecio de sí, la ciudad celestial.", "opts": [{"k": "bueno", "t": "Pero en la vida real las dos ciudades están mezcladas: hay bondad y egoísmo en todas las personas y en todas las instituciones. ¿Cómo distinguirlas?", "r": "En eso estoy de acuerdo: en este mundo las dos ciudades están entremezcladas, y solo al final se separarán. Ninguna institución humana es sin más la ciudad de Dios. Solo Dios ve los corazones.", "why": "Señalas que la distinción no se puede aplicar de forma simple, algo que el propio Agustín reconoce.", "f": ""}, {"k": "flojo", "t": "Yo me quiero a mí mismo y no desprecio a nadie.", "r": "Quererse no es malo. El problema es el desorden: amar más lo que vale menos. La virtud es el orden del amor.", "why": "No respondes a la tesis, que habla de un amor desordenado.", "f": ""}, {"k": "falacia", "t": "Roma fue saqueada después de hacerse cristiana, así que el cristianismo la debilitó.", "r": "Escribí veintidós libros para responder a esa acusación. Roma sufrió desastres mucho antes de Cristo. Que algo ocurra después no prueba que sea su causa.", "why": "Supones que porque algo ocurrió después, fue causado por lo anterior.", "f": "Falsa causa"}]}, {"say": "Nos hiciste para ti, Señor, y nuestro corazón está inquieto hasta que descanse en ti. Por eso ningún bien de este mundo nos basta del todo.", "opts": [{"k": "bueno", "t": "Muchas personas sin fe viven en paz y hacen el bien. ¿No es injusto decir que su corazón está siempre inquieto?", "r": "Veo bondad en ellas, y creo que todo bien viene de Dios, lo sepan o no. Pero tienes razón en algo: no puedo medir el corazón de otro. En mis Confesiones hablo de lo que encontré en el mío.", "why": "Señalas que una experiencia personal no puede generalizarse sin más a todos.", "f": ""}, {"k": "flojo", "t": "Yo no siento ninguna inquietud.", "r": "Yo tampoco la reconocía al principio. Te buscaba fuera, y tú estabas dentro de mí. Tarde te amé.", "why": "Respondes con tu impresión, sin discutir el argumento.", "f": ""}, {"k": "falacia", "t": "Lo enseña la Iglesia desde hace siglos, así que no hay más que hablar.", "r": "Yo creo para comprender, no para dejar de pensar. «Ama mucho la inteligencia», escribí en una carta. Si no das razones, no me ayudas a entender.", "why": "Que algo se haya enseñado durante siglos no basta como argumento.", "f": "Apelación a la tradición"}]}], "fin": {"alto": "Has buscado la verdad con inquietud y con honradez. Esa inquietud es buena: es el comienzo de todo camino hacia dentro.", "medio": "Has empezado a buscar, pero a veces te quedaste fuera de ti. Entra en ti mismo: en el interior habita la verdad.", "bajo": "Te conformaste con respuestas fáciles. Yo también lo hice muchos años. Nunca es tarde para empezar a buscar."}},
);
